#include "PluginProcessor.h"
#include <cstdio>
#include <cmath>
using namespace juce;
static void check(bool ok,const char*what){if(!ok){fprintf(stderr,"FAIL: %s\n",what);std::abort();}}
static void set(SynthMavenProcessor&p,const String&id,float v){p.parameters.getParameter(id)->setValueNotifyingHost(v);}
static void tick(SynthMavenProcessor&p){AudioBuffer<float>b(2,64);MidiBuffer m;p.processBlock(b,m);}
static void click(Component&c,const String&name){for(int i=0;i<c.getNumChildComponents();i++){auto*child=c.getChildComponent(i);if(auto*b=dynamic_cast<TextButton*>(child))if(b->getButtonText()==name){b->setToggleState(true,dontSendNotification);if(b->onClick)b->onClick();return;}click(*child,name);}}
int main(int argc,char**argv){ScopedJuceInitialiser_GUI gui;ScalaScale sc;String error;
 check(ScalaScale::parse("! test\n\n12\n100.\n200.\n300.\n400.\n500.\n600.\n3/2 fifth\n800.\n900.\n1000.\n1100.\n2 ! period\n",sc,error),"ratios, decimal cents, integer ratios, blank description");check(std::abs(sc.period-1200)<.001,"integer 2 is ratio 2/1");check(!ScalaScale::parse("Bad\n2\n0/1\n2/1",sc,error),"reject zero ratio");check(!ScalaScale::parse("Bad\n2\nNaN\n2/1",sc,error),"reject nonfinite");check(!ScalaScale::parse("Bad\n3\n100.\n2/1",sc,error),"reject missing degrees");
 sm_context*a=sm_create(),*bctx=sm_create();sm_select_program(a,0);sm_select_program(bctx,0);double table[128]{};table[60]=-50;sm_set_tuning(bctx,table);uint8_t note[]={0x90,60,100};sm_midi(a,note,3);sm_midi(bctx,note,3);std::vector<float>dry(8192),tuned(8192);sm_render(a,dry.data(),4096);sm_render(bctx,tuned.data(),4096);double difference=0;for(size_t i=0;i<dry.size();i++)difference+=std::abs(dry[i]-tuned[i]);check(difference>1,"tuning changes actual DSP audio");sm_destroy(a);sm_destroy(bctx);
 SynthMavenProcessor p;p.prepareToPlay(48000,64);p.tuningPreset(0,1);tick(p);check(std::abs(p.appliedTuningOffset(0,64)+50)<.025,"Rast E half-flat");check(std::abs(p.appliedTuningOffset(1,64))<.025,"layer tuning isolation");p.tuningPreset(8,2);set(p,"masterTuning",1);tick(p);for(int l=0;l<8;l++){check(std::abs(p.appliedTuningOffset(l,62)+50)<.025,"master tunes every layer");check(std::abs(p.appliedTuningOffset(l,64))<.025,"master replaces rather than adds layer scale");}set(p,"masterTuning",0);tick(p);check(std::abs(p.appliedTuningOffset(0,64)+50)<.025,"master off restores layer tuning");
 p.storeTuning(0,2);p.resetTuning(0);p.recallTuning(0,2);check(std::abs(p.tuningOffset(0,64)+50)<.001,"five-memory store recall");String edo="19 EDO\n19\n";for(int n=1;n<=19;n++)edo+=String(1200.*n/19,8)+"\n";check(p.loadScala(1,edo,error),"19 EDO import");tick(p);check(std::abs(p.appliedTuningOffset(1,79)+700)<.025,"19 keys span octave");set(p,p.tuningId(1,"bypass"),1);tick(p);check(std::abs(p.appliedTuningOffset(1,79))<.001,"bypass ET");set(p,p.tuningId(1,"bypass"),0);set(p,"masterTuning",1);MemoryBlock saved;p.getStateInformation(saved);SynthMavenProcessor q;q.setStateInformation(saved.getData(),(int)saved.getSize());q.prepareToPlay(48000,64);tick(q);check(q.parameters.getRawParameterValue("masterTuning")->load()>.5,"master toggle persists");set(q,"masterTuning",0);tick(q);check(std::abs(q.appliedTuningOffset(1,79)+700)<.025,"Scala content persists");q.resetTuning(0);q.recallTuning(0,2);check(std::abs(q.tuningOffset(0,64)+50)<.001,"tuning memories persist");check(q.assignMapping(0,23,"masterTuning"),"master toggle MIDI mappable");MidiBuffer midi;AudioBuffer<float>b(2,64);midi.addEvent(MidiMessage::controllerEvent(1,23,127),0);q.processBlock(b,midi);tick(q);check(std::abs(q.appliedTuningOffset(0,62)+50)<.025,"master controlled over MIDI");
 if(argc>1){MemoryBlock flushed;q.getStateInformation(flushed);std::unique_ptr<AudioProcessorEditor>editor(q.createEditor());click(*editor,"TUNING");Image image(Image::ARGB,editor->getWidth(),editor->getHeight(),true);Graphics g(image);editor->paintEntireComponent(g,true);File file(argv[1]);auto stream=file.createOutputStream();stream->setPosition(0);stream->truncate();PNGImageFormat png;png.writeImageToStream(image,*stream);}
 puts("PASS: Scala parser; per-layer tuning; all-eight-layer master override and restoration; bypass; memories; saved recall; MIDI master toggle; tuning GUI.");}
